/* global test expect */
import { DateTime } from "../../src/luxon";

const fmt = dt => dt.isValid ? dt.toISO() : "INVALID:" + dt.invalidReason;

test("probe", () => {
  const out = [];
  // invariant: year Y and Y+1900 behave identically modulo 1900 years
  const check = (label, a, b) => {
    const ay = a.year, by = b.year;
    if (!a.isValid || !b.isValid) { out.push(`${label}: invalid a=${fmt(a)} b=${fmt(b)}`); return; }
    if (ay - by !== -1900 || a.month !== b.month || a.day !== b.day || a.hour !== b.hour) {
      out.push(`${label}: MISMATCH ${fmt(a)} vs ${fmt(b)}`);
    }
  };
  for (const m of [1,2,3,11,12]) {
    for (const d of [1,15,28]) {
      const a0 = DateTime.utc(99, m, d), b0 = DateTime.utc(1999, m, d);
      check(`base ${m}/${d}`, a0, b0);
      for (const n of [1,2,30,60,90,365,-1,-30,-60,-365]) {
        check(`plus ${n} ${m}/${d}`, a0.plus({days:n}), b0.plus({days:n}));
        check(`minus ${-n} ${m}/${d}`, a0.minus({days:-n}), b0.minus({days:-n}));
      }
      for (const n of [1,2,11,12,-1,-11]) {
        check(`plusM ${n} ${m}/${d}`, a0.plus({months:n}), b0.plus({months:n}));
      }
    }
  }
  // roundtrip
  for (const y of [0,1,50,99,100]) {
    for (const [m,d] of [[1,1],[2,28],[3,1],[12,31]]) {
      const dt = DateTime.utc(y,m,d);
      const iso = dt.toISO();
      const back = DateTime.fromISO(iso, {setZone:true});
      if (back.year !== y || back.month !== m || back.day !== d) out.push(`roundtrip ${y}-${m}-${d}: ${iso} -> ${fmt(back)}`);
    }
  }
  process.stdout.write("issues: " + out.length + "\n" + out.slice(0,40).join("\n") + "\n");
});
EOF
